  --color-primary-600: #4DB98A;
  --color-primary-700: #74CDA6;
  --color-primary-800: #A5E2C6;
  --color-primary-900: #D4F1E0;

  /* Secondary - Utah Crimson → 네온 레드 (다크 위 밝게, Hot Now 네온) */
